use vstd::prelude::*;

verus! {

/// Positional Chebyshev-style weights:
/// for length n > 0:
///   w[0] = 0.5, w[n-1] = 0.5, and all interior indices are 1.0.
spec fn cheb_weight_at(i: nat, n: nat) -> f32
    recommends n > 0
{
    if i == 0 || i + 1 == n { 0.5 } else { 1.0 }
}

fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: int|
            0 <= i < result.len() ==> result[i] ==
                cheb_weight_at(i as nat, result.len() as nat),
{
    let n = x.len();
    let mut w: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            n == x.len(),
            n > 0,
            w.len() == i,
            i <= n,
            forall|j: int|
                0 <= j < i ==> w[j] == cheb_weight_at(j as nat, n as nat),
        decreases n - i,
    {
        if i == 0 || i + 1 == n {
            w.push(0.5);
        } else {
            w.push(1.0);
        }
        i = i + 1;
    }

    w
}

} // verus!

